function navigate(view,actor){s.view=view;if(actor)s.actor=actor;s.pick=null;s.notice='';s.secretsFor='';render();window.scrollTo(0,0)}
function goHome(){if(s.actor==='prospect'&&s.prospectId){navigate('dashboard','prospect');return}if(s.actor==='prospect'&&!s.liveInvite){navigate('dashboard','prospect');return}if(s.liveInvite){navigate(['request','chat','secondFive','secondResults','email','tests','declined','ended'].includes(s.phase)?'dashboard':s.prospect.answers.length>=5?'results':'invitee','prospect');return}navigate(s.member.answers.length?'dashboard':'landing','member')}
function nextJoinStep(){const n=$('joinName').value.trim(),c=$('joinContact').value.trim().toLowerCase();if(!n||!validContact(c)){$('joinError').textContent=CELL_ENABLED?'Enter your name and an email or ten-digit cell number.':'Enter your first name and email.';return}if(!$('joinAgree').checked){$('joinError').textContent='Confirm you’re 18 or older and agree to the Terms and Privacy Policy.';return}s.member.name=n;s.member.contact=c;s.member.agreed=true;sendCode(c,'joinError').then(ok=>{if(ok){s.signinEmail=c;s.joinStep='joinCode';render();$('signinCode')?.focus()}})}
function backToDetails(){cameraStream?.getTracks().forEach(t=>t.stop());cameraStream=null;s.joinStep=1;render()}
let cameraStream=null;
async function openCamera(){
 const error=$(s.view==='request'?'requestError':s.view==='revealPhoto'?'revealPhotoError':'joinError');error.textContent='';
 if(!navigator.mediaDevices?.getUserMedia){error.textContent='No camera is available in this browser. Use CHOOSE FILE PHOTO.';return}
 try{
  cameraStream?.getTracks().forEach(t=>t.stop());
  cameraStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user'},audio:false});
  const video=$('cameraPreview');video.srcObject=cameraStream;video.hidden=false;$('captureBtn').hidden=false;
  await video.play();
 }catch(e){cameraStream?.getTracks().forEach(t=>t.stop());cameraStream=null;const video=$('cameraPreview');if(video){video.srcObject=null;video.hidden=true}const capture=$('captureBtn');if(capture)capture.hidden=true;error.textContent=e.name==='NotAllowedError'?'Camera access was blocked. Allow camera access in your browser, or use CHOOSE FILE PHOTO.':'No camera was found. Use CHOOSE FILE PHOTO.'}
}
async function captureCamera(){
 const video=$('cameraPreview');if(!video?.videoWidth){$(s.view==='request'?'requestError':s.view==='revealPhoto'?'revealPhotoError':'joinError').textContent='Wait for the camera, then capture your picture.';return}
 const canvas=$('cameraCanvas'),side=Math.min(video.videoWidth,video.videoHeight);canvas.width=canvas.height=320;
 canvas.getContext('2d').drawImage(video,(video.videoWidth-side)/2,(video.videoHeight-side)/2,side,side,0,0,320,320);
 const picture=canvas.toDataURL('image/jpeg',.78);if(s.view==='landing')s.member.photo=picture;else s.prospect.photo=picture;
 cameraStream?.getTracks().forEach(t=>t.stop());cameraStream=null;
 video.srcObject=null;video.hidden=true;$('captureBtn').hidden=true;
 if(s.view==='landing')finishRegistration();
 else if(s.view==='revealPhoto')render();
 else{const n=$('prospectName').value,c=$('prospectContact').value;render();$('prospectName').value=n;$('prospectContact').value=c}
 save();
}
async function uploadPhoto(event,actor){
 const file=event.target.files?.[0];if(!file)return;
 const target=actor==='member'?'joinError':s.view==='revealPhoto'?'revealPhotoError':'requestError';
 if(!file.type.startsWith('image/')){$(target).textContent='Choose an image file.';return}
 try{
  const data=await new Promise((resolve,reject)=>{
   const img=new Image(),url=URL.createObjectURL(file);
   img.onload=()=>{try{const canvas=document.createElement('canvas');canvas.width=canvas.height=320;const side=Math.min(img.width,img.height);canvas.getContext('2d').drawImage(img,(img.width-side)/2,(img.height-side)/2,side,side,0,0,320,320);resolve(canvas.toDataURL('image/jpeg',.78))}catch(e){reject(e)}finally{URL.revokeObjectURL(url)}};
   img.onerror=()=>{URL.revokeObjectURL(url);reject(Error('Could not open this picture.'))};img.src=url;
  });
  if(actor==='member')s.member.photo=data;else s.prospect.photo=data;
  if(actor==='member'){cameraStream?.getTracks().forEach(t=>t.stop());cameraStream=null;const v=$('cameraPreview');if(v){v.srcObject=null;v.hidden=true}$(target).textContent='';finishRegistration()}
  else if(s.view==='revealPhoto'){render()}else{cameraStream?.getTracks().forEach(t=>t.stop());cameraStream=null;const n=$('prospectName').value,c=$('prospectContact').value;render();$('prospectName').value=n;$('prospectContact').value=c}
  save();
 }catch(e){$(target).textContent=e.message||'Could not open this picture.'}
}
async function finishRegistration(){if(!s.member.name||!s.member.contact||!s.member.photo){$('joinError').textContent='Complete your details and picture to continue.';return}try{const registered=await memberApi({action:'register',...s.member});s.memberId=registered.member.id;s.member.verified=registered.member.verified;s.modal='welcome';renderModal();save()}catch(e){$('joinError').textContent=e.message}}
function enterGame(){s.modal='';navigate('dashboard','member')}
function startMemberQuestions(){s.actor='member';s.view='dashboard';s.memberQuestionsOpen=true;s.pick=null;render();$('memberQuestion')?.scrollIntoView({behavior:'smooth',block:'nearest'})}
function pick(i){s.pick=i;document.querySelectorAll('.option').forEach((el,j)=>{el.classList.toggle('on',j===i);el.setAttribute('aria-pressed',j===i)})}
async function answerQuestion(){if(s.pick===null){$('answerError').textContent='Pick one answer to continue.';return}let member=s.actor==='member',arr=member?s.member.answers:s.prospect.answers;arr.push(s.pick);s.pick=null;if(member&&arr.length===10){try{if(!s.memberId){const data=await memberApi({action:'register',...s.member});s.memberId=data.member.id}else await memberApi({action:'answers',answers:arr});s.memberQuestionsOpen=false;s.phase='ready';navigate('dashboard','member')}catch(e){arr.pop();$('answerError').textContent=e.message}}else if(!member&&arr.length===5){s.phase='awaitingPhoto';navigate('revealPhoto','prospect')}else if(!member&&arr.length===10){try{if(s.liveInvite)await memberApi({action:'answers',answers:arr});if(s.phase==='secondFive'){if(s.liveInvite)await connectionApi({action:'second',token:s.liveToken,answers:arr});s.phase='secondResults';navigate('results','prospect')}else{s.phase=s.resumePhase||'firstResults';navigate('dashboard','prospect')}}catch(e){arr.pop();$('answerError').textContent=e.message}}else render()}
let qrPending=null;
const validQrInvite=()=>s.qrInvite&&new Date(s.qrInvite.expiresAt).getTime()>Date.now()+60000;
function primeQrInvite(){if(validQrInvite()||qrPending)return qrPending;return makeQrInvite(true)}
function openInvite(){if(owner().answers.length!==10)return;if(!validQrInvite())s.qrInvite=null;s.modal='qr';s.qrError='';renderModal();if(!s.qrInvite)primeQrInvite()}
function makeQrInvite(background=false){
 if(qrPending)return qrPending;
 s.qrInvite=null;s.qrError='';if(!background&&s.modal==='qr')renderModal();
 qrPending=(async()=>{
  const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),20000);
  try{
   const response=await fetch('/api/qr',{method:'POST',credentials:'same-origin',signal:controller.signal});
   const data=await response.json();if(!response.ok)throw Object.assign(Error(data.error||'Could not make your code.'),{needsVerify:!!data.needsVerify});
   if(!globalThis.ChempatQR?.toString)throw Error('Code display is still loading. Refresh this page and try again.');
   data.svg=await ChempatQR.toString(data.url,{type:'svg',errorCorrectionLevel:'Q',margin:3,width:384,color:{dark:'#173b4c',light:'#ffffff'}});
   s.qrInvite=data;
   if(s.actor==='member'){s.liveMember=true;s.liveId=data.id;s.selectedChempat=data.id;refreshLive()}
   else{s.outgoing.unshift({id:data.id,name:'Someone',status:'invited',channel:'qr',claimed:false});s.selectedChempat=data.id;refreshOutgoing()}
   save();
  }catch(e){s.qrNeedsVerify=!!e.needsVerify;s.qrError=e.needsVerify?'Confirm your email to show your code.':e.name==='AbortError'?'The code is taking too long. Tap NEW CODE to try again.':e.message||'Could not make your code.'}
  finally{clearTimeout(timeout);qrPending=null;if(s.modal==='qr')renderModal()}
  return s.qrInvite;
 })();return qrPending;
}
function updateQrCountdown(){const timer=$('qrTimer');if(!timer||!s.qrInvite)return;const seconds=Math.max(0,Math.ceil((new Date(s.qrInvite.expiresAt).getTime()-Date.now())/1000));timer.textContent=seconds?`Ready for ${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`:'Code expired · make a new one';if(!seconds&&!timer.dataset.expired){timer.dataset.expired='1';renderModal()}}
function closeInvite(e){if(e&&e.target!==e.currentTarget)return;const wasInvitation=['qr','send'].includes(s.modal);s.modal='';renderModal();if(wasInvitation&&s.qrInvite){s.qrInvite=null;primeQrInvite()}}
function inviteMode(m){s.modal=m;renderModal()}
function openOutgoing(id){if(!s.outgoing.some(item=>item.id===id))return;s.selectedOutgoing=id;s.modal='outgoing';renderModal();refreshOutgoing()}
function renderOutgoing(){const item=s.outgoing.find(c=>c.id===s.selectedOutgoing);if(!item){s.modal='';$('modalHost').innerHTML='';return}const theirs=item.answers||[],ours=s.prospect.answers,showFive=theirs.length>=5;const status=({invited:'Invitation sent. Their first five are next.',firstResults:'Their first five are in.',request:'They want to connect with you.',chat:'Your Private Chat is open.',secondResults:'Your next five are in.',email:'Email shared.',declined:'Connection passed.',ended:'Connection ended.'})[item.status]||'Your invitation is open.';$('modalHost').innerHTML=`<div class="modalBackdrop" onclick="closeInvite(event)"><section class="modal outgoingModal" role="dialog" aria-modal="true" aria-labelledby="outgoingTitle"><button class="close" type="button" aria-label="Close" onclick="closeInvite()">×</button><div class="eyebrow">YOUR CHEMPAT</div><h2 id="outgoingTitle">${esc(first(item.name))}</h2><div class="outgoingFaces"><img src="${pic(s.prospect.photo)}" alt="${esc(name('prospect'))}">${item.photo?`<img src="${pic(item.photo)}" alt="${esc(first(item.name))}">`:`<span class="face">${esc(first(item.name)[0])}</span>`}</div><p>${esc(status)}</p>${showFive?`<details class="outgoingFive"><summary>OUR FIRST FIVE →</summary>${QUESTIONS.slice(0,5).map((q,i)=>`<div><b>${esc(q.topic)}</b><span>You: ${esc(q.a[ours[i]]||'—')}</span><span>${esc(first(item.name))}: ${esc(q.a[theirs[i]]||'—')}</span></div>`).join('')}</details>`:''}${item.status==='request'?`<div class="row">${button('ACCEPT & CHAT →',"decideOutgoing('accept')")}${button('PASS',"decideOutgoing('decline')",'light')}</div>`:''}${['chat','secondResults','email','tests'].includes(item.status)?`<div class="outgoingMessages">${(item.messages||[]).map(m=>`<p class="${m.by==='member'?'mine':''}"><b>${esc(m.by==='member'?'You':first(item.name))}</b> ${esc(m.text)}</p>`).join('')}</div><input id="outgoingMessage" class="joinInput" maxlength="500" aria-label="Private message" placeholder="Say something…" onkeydown="if(event.key==='Enter')sendOutgoingMessage()"><div class="row">${button('SEND →','sendOutgoingMessage()','alt')}</div>`:''}<p class="error" id="outgoingError" role="alert"></p></section></div>`}
async function decideOutgoing(decision){const item=s.outgoing.find(c=>c.id===s.selectedOutgoing);if(!item)return;try{await connectionApi({action:'decision',id:item.id,decision});item.status=decision==='accept'?'chat':'declined';render();await refreshOutgoing()}catch(e){if(gate(e,()=>decideOutgoing(decision)))return;$('outgoingError').textContent=e.message}}
async function sendOutgoingMessage(){const item=s.outgoing.find(c=>c.id===s.selectedOutgoing),field=$('outgoingMessage'),value=field?.value.trim();if(!item||!value)return;try{const data=await connectionApi({action:'message',id:item.id,text:value});item.messages=data.messages;render()}catch(e){if(gate(e,()=>sendOutgoingMessage()))return;$('outgoingError').textContent=e.message}}
async function refreshOutgoing(){if(!s.liveInvite||!s.prospectId)return;try{const response=await fetch('/api/connection?inbox=1',{credentials:'same-origin',cache:'no-store'});if(!response.ok)return;const data=await response.json(),old=JSON.stringify(s.outgoing);s.outgoing=(data.connections||[]).map(c=>({id:c.id,name:c.prospect_name||c.recipient_name||'Someone',email:c.recipient_email,photo:c.prospect_photo,answers:c.prospect_answers,status:c.status,channel:c.channel,claimed:c.claimed,messages:c.messages}));if(old!==JSON.stringify(s.outgoing)&&s.view==='dashboard'&&document.activeElement?.id!=='outgoingMessage')render();save()}catch{}}
function renderModal(){let host=$('modalHost');if(!s.modal){host.innerHTML='';return}if(s.modal==='outgoing'){renderOutgoing();return}if(s.modal==='end'){renderEnd();return}if(s.modal==='logout'){renderLogout();return}if(s.modal==='verifyEmail'){renderVerifyEmail();return}if(s.modal==='welcome'){host.innerHTML=`<div class="modalBackdrop" onclick="closeInvite(event)"><section class="modal welcomeModal" role="dialog" aria-modal="true" aria-labelledby="welcomeTitle"><button class="close" type="button" aria-label="Close" onclick="closeInvite()">×</button><div class="eyebrow">3 · YOUR PAGE</div><div class="welcomeFace">${face('member')}</div><h2 id="welcomeTitle">Ready to play, ${esc(name('member'))}?</h2><p>Your page is next. Answer ten quick situations to make it yours, then invite someone into your first five.</p>${button('STEP 3 — OPEN MY PAGE →','enterGame()')}<p class="small">Your page is ready for you.</p></section></div>`;return}host.innerHTML=`<div class="modalBackdrop" onclick="closeInvite(event)"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="inviteTitle"><button class="close" type="button" aria-label="Close invitation" onclick="closeInvite()">×</button><div class="eyebrow">YOUR INVITATION</div><h2 id="inviteTitle">${s.modal==='qr'?`I’ll tell you five secrets about me. Want to see if we vibe?`:'I caught your vibe. Let’s talk.'}</h2>${s.modal==='qr'?`<div class="invitePair"><div>${owner().photo?`<img class="portrait" src="${pic(owner().photo)}" alt="${esc(first(owner().name))}">`:face(s.actor)}<b style="display:block;margin-top:8px">${esc(first(owner().name))}</b></div><div>${s.qrInvite&&new Date(s.qrInvite.expiresAt).getTime()>Date.now()?`<img class="liveQr" src="data:image/svg+xml;charset=utf-8,${encodeURIComponent(s.qrInvite.svg)}" alt="Scan to open ${esc(first(owner().name))}'s invitation"><small id="qrTimer" class="qrTimer" aria-live="off"></small>`:`<div class="qrWaiting">${s.qrError?esc(s.qrError):s.qrInvite?'Code expired.':'Making your code…'}</div>`}</div></div>${s.qrNeedsVerify?button('CONFIRM MY EMAIL →','verifyForQr()'):s.qrInvite&&new Date(s.qrInvite.expiresAt).getTime()<=Date.now()||s.qrError?button('NEW CODE →','makeQrInvite()','alt'):''}<button class="link" type="button" onclick="inviteMode('send')">Can’t scan? Send it instead →</button>`:`<div class="modalForm"><p class="small">Send your picture and invitation to their email. We’ll verify your email first.</p><label class="field">Their name<input id="inviteName" autocomplete="given-name" maxlength="50" placeholder="First name"></label><label class="field">Their email<input id="inviteContact" type="email" autocomplete="email" placeholder="them@example.com"></label><div class="row">${button('SEND INVITATION →','prepareInvite()')}</div><p id="inviteError" class="error" role="alert"></p><button class="link" type="button" onclick="inviteMode('qr')">← Show code instead</button></div>`}</section></div>`;updateQrCountdown()}
async function memberApi(data){const response=await fetch('/api/member',{method:'POST',headers:{'content-type':'application/json'},credentials:'same-origin',body:JSON.stringify(data)});const body=await response.json();if(!response.ok)throw Object.assign(Error(body.error||'Could not save your member page.'),{status:response.status,needsVerify:!!body.needsVerify,exists:!!body.exists});return body}
