 if(s.liveMember){const response=await fetch('/api/connection?inbox=1',{credentials:'same-origin',cache:'no-store'}),data=await response.json();if(!response.ok)throw Error(data.error);const before=JSON.stringify(s.inbox),previous=s.phase;s.inbox=data.connections||[];if(!s.liveId&&s.inbox.length)s.liveId=s.inbox[0].id;const selected=s.inbox.find(c=>c.id===s.liveId);if(selected)applyConnection(selected);if(before!==JSON.stringify(s.inbox)&&['dashboard','conversation','request','results'].includes(s.view)&&document.activeElement?.id!=='message')render();if(previous!=='request'&&s.phase==='request'&&s.view==='dashboard')render()}
