async function resumeMember(){try{const response=await fetch('/api/member',{credentials:'same-origin',cache:'no-store'});if(!response.ok)return;const {member}=await response.json();if(s.memberId||s.prospectId)return;s.member={name:member.name,contact:member.contact,photo:member.photo,answers:member.answers||[],verified:member.verified};s.memberId=member.id;s.phase=s.member.answers.length===10?'ready':'registration';s.liveMember=true;navigate('dashboard','member');refreshLive()}catch{}}
if(invitationToken)openEmailInvitation();else{render();if(s.liveMember||s.liveInvite)refreshLive();else if(s.view==='landing'&&!s.member.name)resumeMember()}
